/* English build of signup.js — generated by cli/i18n.php, do not edit */
/* Create account: اقتراح Account name from Network name والتحقق from توفّره */
(function (document) {
  'use strict';
  var form = document.querySelector('[data-signup]');
  if (!form) { return; }
  var name = form.querySelector('[name=name]');
  var slug = form.querySelector('[data-slug]');
  var status = form.querySelector('[data-slug-status]');
  var url = form.getAttribute('data-check');
  var touched = slug.value !== '';
  var timer = null;
  var seq = 0;
  function show(ok, msg) {
    status.className = 'slug-status ' + (ok ? 'is-ok' : 'is-bad');
    status.innerHTML = (window.SN ? SN.icon(ok ? 'circle-check' : 'circle-alert') : '') + '<span></span>';
    status.querySelector('span').textContent = msg;
  }
  function check(params) {
    var my = ++seq;
    fetch(url + '?' + new URLSearchParams(params), { headers: { Accept: 'application/json' } })
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (my !== seq) { return; }
        if (params.name && !touched) { slug.value = d.slug; }
        if (slug.value) { show(d.ok, d.ok ? 'Available' : d.message); }
      }).catch(function () {});
  }
  name.addEventListener('input', function () {
    if (touched) { return; }
    clearTimeout(timer);
    timer = setTimeout(function () { if (name.value.trim().length > 1) { check({ name: name.value.trim() }); } }, 350);
  });
  // Username: أحمر مع ✗ إن كان مستخدماً, and Green مع ✓ إن كان متاحاً, أثناء الكتابة
  var user = form.querySelector('[data-username]');
  var userBox = form.querySelector('[data-user-field]');
  var userNote = form.querySelector('[data-user-status]');
  var userUrl = form.getAttribute('data-user-check');
  var userTimer = null;
  var userSeq = 0;
  function userState(state, msg) {
    userBox.classList.toggle('is-free', state === 'free');
    userBox.classList.toggle('is-taken', state === 'taken' || state === 'invalid');
    if (!state) { userNote.className = 'slug-status'; userNote.textContent = ''; return; }
    var ok = state === 'free';
    userNote.className = 'slug-status ' + (ok ? 'is-ok' : 'is-bad');
    userNote.innerHTML = (window.SN ? SN.icon(ok ? 'circle-check' : 'circle-x') : '') + '<span></span>';
    userNote.querySelector('span').textContent = msg;
  }
  if (user && userUrl) {
    var checkUser = function () {
      var v = user.value.trim();
      clearTimeout(userTimer);
      if (!v) { userState('', ''); return; }
      userTimer = setTimeout(function () {
        var my = ++userSeq;
        fetch(userUrl + '?' + new URLSearchParams({ username: v }), { headers: { Accept: 'application/json' } })
          .then(function (r) { return r.json(); })
          .then(function (d) { if (my === userSeq && user.value.trim() === v && d.state !== 'wait') { userState(d.state, d.message); } })
          .catch(function () {});
      }, 350);
    };
    user.addEventListener('input', checkUser);
    if (user.value.trim()) { checkUser(); }
  }

  slug.addEventListener('input', function () {
    touched = true;
    var v = slug.value.toLowerCase().replace(/[^a-z0-9-]/g, '');
    if (v !== slug.value) { slug.value = v; }
    clearTimeout(timer);
    if (v.length < 3) { status.className = 'slug-status'; status.textContent = ''; return; }
    timer = setTimeout(function () { check({ slug: v }); }, 300);
  });

})(document);